[package]
name = "firecraft"
version = "0.1.0"
edition = "2021"
description = "FireCraft - Modern vector graphics editor, inspired by Adobe Fireworks CS6"

[dependencies]
eframe = { version = "0.28", features = ["default"] }
egui_extras = { version = "0.28", features = ["all"] }
image = { version = "0.25", default-features = false, features = ["png", "jpeg", "webp", "svg", "bmp", "gif", "ico", "tga", "hdr"] }
serde = { version = "1", features = ["derive"] }
tracing = "0.1"
tracing-subscriber = "0.1"

mod app;

fn main() -> Result<(), eframe::Error> {
    // Initialize tracing (best-effort)
    let _ = tracing_subscriber::subscriber::set_global_default(
        tracing_subscriber::FmtSubscriber::new(),
    );

    let native_options = eframe::NativeOptions {
        viewport: eframe::egui::ViewportBuilder::new()
            .with_active(false)
            .with_window_level(eframe::egui::WindowLevel::AlwaysOnBottom)
            .with_titlebar_shown(true)
            .with_titlebar_visible(true)
            .with_inner_size([1400.0, 900.0])
            .build(),
        ..Default::default()
    };

    eframe::run_native(
        "FireCraft",
        native_options,
        Box::new(|cc| {
            // Set up default context
            Ok(Box::new(app::FireCraftApp::new(cc)))
        }),
    )
}

use eframe::egui;
use std::sync::Mutex;

use canvas::Canvas;
use doc::Document;
use history::History;
use tools::Tool;
use panels::{LeftPanel, RightPanel};

pub struct FireCraftApp {
    theme: Theme,
    current_tool: Tool,
    active_doc: Option<Mutex<Document>>,
    history: History,
    left_panel: LeftPanel,
    right_panel: RightPanel,
    menu_bar_state: MenuBar,
}

use eframe::egui;

/// Represents a single path/curve segment (quadratic bezier for vector shapes)
#[derive(Debug, Clone)]
pub struct PathSegment {
    pub points: Vec<egui::Pos2>,
    pub closed: bool,
    pub fill_color: Option<egui::Color32>,
    pub stroke_color: Option<egui::Color32>,
    pub stroke_width: f32,
}

/// A drawable object (vector shape, bitmap, text)
#[derive(Debug, Clone)]
pub enum Drawable {
    Vector {
        path: PathSegment,
        layer_name: String,
    },
    Bitmap {
        image: egui::ColorImage,
        layer_name: String,
        x: f32,
        y: f32,
    },
    Text {
        text: String,
        font_size: f32,
        color: egui::Color32,
        pos: egui::Pos2,
        layer_name: String,
    },
}

/// A layer in the document
#[derive(Debug, Clone)]
pub struct Layer {
    pub name: String,
    pub visible: bool,
    pub locked: bool,
    pub opacity: f32, // 0.0 - 1.0
    pub drawables: Vec<Drawable>,
}

use crate::page::Page;

#[derive(Debug, Clone)]
pub struct Document {
    pub pages: Vec<Page>,
    pub current_page_index: usize,
    pub name: String,
    pub path: Option<String>,
    pub history: Vec<DocState>,
    pub history_index: usize,
}

#[derive(Debug, Clone)]
pub struct DocState {
    pub description: String,
}

impl Document {
    pub fn new(name: &str, width: f32, height: f32) -> Self {
        Document {
            pages: vec![Page::new(name, width, height, egui::Color32::from_rgb(255, 255, 255))],
            current_page_index: 0,
            name: name.to_string(),
            path: None,
            history: Vec::new(),
            history_index: 0,
        }
    }

    pub fn current_page(&self) -> &Page {
        &self.pages[self.current_page_index]
    }

    pub fn current_page_mut(&mut self) -> &mut Page {
        &mut self.pages[self.current_page_index]
    }

    pub fn add_layer(&mut self, layer_name: &str) {
        self.current_page_mut().layers.push(crate::paths::Layer::new(layer_name));
    }

    pub fn add_page(&mut self, name: &str, width: f32, height: f32) {
        self.pages.push(Page::new(name, width, height, egui::Color32::from_rgb(255, 255, 255)));
    }

    pub fn save_state(&mut self, description: &str) {
        self.history.truncate(self.history_index);
        self.history.push(DocState {
            description: description.to_string(),
        });
        self.history_index = self.history.len();
    }

    pub fn undo(&mut self) -> bool {
        if self.history_index > 0 {
            self.history_index -= 1;
            true
        } else {
            false
        }
    }

    pub fn redo(&mut self) -> bool {
        if self.history_index < self.history.len() {
            self.history_index += 1;
            true
        } else {
            false
        }
    }
}

#[derive(Debug, Clone)]
pub struct History {
    pub states: Vec<HistoryState>,
    pub index: usize,
}

#[derive(Debug, Clone)]
pub struct HistoryState {
    pub description: String,
}

impl History {
    pub fn new() -> Self {
        History {
            states: Vec::new(),
            index: 0,
        }
    }

    pub fn push(&mut self, description: &str) {
        self.states.truncate(self.index);
        self.states.push(HistoryState {
            description: description.to_string(),
        });
        self.index = self.states.len();
    }

    pub fn undo(&mut self) -> bool {
        if self.index > 0 {
            self.index -= 1;
            true
        } else {
            false
        }
    }

    pub fn redo(&mut self) -> bool {
        if self.index < self.states.len() {
            self.index += 1;
            true
        } else {
            false
        }
    }

    pub fn can_undo(&self) -> bool {
        self.index > 0
    }

    pub fn can_redo(&self) -> bool {
        self.index < self.states.len()
    }
}

