use std::sync::Mutex;

use eframe::egui;
use eframe::App;

use canvas::Canvas;
use doc::Document;
use history::History;
use panels::{LeftPanel, RightPanel};
use tools::Tool;

use crate::page::ExportFormat;

pub enum Theme {
    Dark,
    Light,
}

pub struct MenuState {
    file_open: bool,
    edit_open: bool,
    view_open: bool,
    modify_open: bool,
    text_open: bool,
    select_open: bool,
    filters_open: bool,
    bitmap_open: bool,
    publish_open: bool,
    window_open: bool,
    help_open: bool,
}

pub struct FireCraftApp {
    theme: Theme,
    current_tool: Tool,
    canvas: Canvas,
    doc: Option<Mutex<Document>>,
    history: History,
    left_panel: LeftPanel,
    right_panel: RightPanel,
    menu_state: MenuState,
    show_new_doc_dialog: bool,
    show_export_dialog: bool,
    show_about_dialog: bool,
    show_export_format: ExportFormat,
    new_doc_name: String,
    new_doc_width: f32,
    new_doc_height: f32,
    new_doc_bg_color: String,
    status_text: String,
}

impl FireCraftApp {
    pub fn new(_cc: &eframe::CreationContext<'_>) -> Self {
        let theme = Theme::Dark;
        let mut app = FireCraftApp {
            theme,
            current_tool: Tool::Select,
            canvas: Canvas::new(),
            doc: None,
            history: History::new(),
            left_panel: LeftPanel::new(),
            right_panel: RightPanel::new(),
            menu_state: MenuState {
                file_open: false,
                edit_open: false,
                view_open: false,
                modify_open: false,
                text_open: false,
                select_open: false,
                filters_open: false,
                bitmap_open: false,
                publish_open: false,
                window_open: false,
                help_open: false,
            },
            show_new_doc_dialog: false,
            show_export_dialog: false,
            show_about_dialog: false,
            show_export_format: ExportFormat::Png,
            new_doc_name: "Untitled".to_string(),
            new_doc_width: 800.0,
            new_doc_height: 600.0,
            new_doc_bg_color: "white".to_string(),
            status_text: "FireCraft ready.".to_string(),
        };
        app.create_new_document("Untitled-1", 800.0, 600.0, "white");
        app
    }

    fn create_new_document(&mut self, name: &str, width: f32, height: f32, bg: &str) {
        let bg_color = match bg {
            "white" => egui::Color32::from_rgb(255, 255, 255),
            "transparent" => egui::Color32::from_argba(0, 0, 0, 0),
            "black" => egui::Color32::from_rgb(0, 0, 0),
            "gray" => egui::Color32::from_rgb(128, 128, 128),
            _ => egui::Color32::from_rgb(255, 255, 255),
        };
        let mut doc = Document::new(name, width, height);
        let page = doc.current_page_mut();
        page.bg_color = bg_color;
        self.doc = Some(Mutex::new(doc));
    }
}

