use std::sync::Mutex;

use eframe::egui::{self, App, Modifiers, Key};

use canvas::Canvas;
use doc::Document;
use history::History;
use panels::{LeftPanel, RightPanel};
use tools::Tool;

use crate::page::ExportFormat;

pub enum Theme { Dark, Light }

pub struct MenuState {
    file_open: bool, edit_open: bool, view_open: bool, modify_open: bool,
    text_open: bool, select_open: bool, filters_open: bool, bitmap_open: bool,
    publish_open: bool, window_open: bool, help_open: bool,
}

pub struct FireCraftApp {
    theme: Theme,
    canvas: Canvas,
    doc: Option<Mutex<Document>>,
    history: History,
    left_panel: LeftPanel,
    right_panel: RightPanel,
    menu_state: MenuState,
    show_new_doc_dialog: bool,
    show_export_dialog: bool,
    show_about_dialog: bool,
    show_export_format: ExportFormat,
    new_doc_name: String,
    new_doc_width: f32,
    new_doc_height: f32,
    new_doc_bg_color: String,
    status_text: String,
}

impl FireCraftApp {
    pub fn new(_cc: &eframe::CreationContext<'_>) -> Self {
        Self {
            theme: Theme::Dark,
            canvas: Canvas::new(),
            doc: None,
            history: History::new(),
            left_panel: LeftPanel::new(),
            right_panel: RightPanel::new(),
            menu_state: MenuState {
                file_open: false, edit_open: false, view_open: false, modify_open: false,
                text_open: false, select_open: false, filters_open: false, bitmap_open: false,
                publish_open: false, window_open: false, help_open: false,
            },
            show_new_doc_dialog: false,
            show_export_dialog: false,
            show_about_dialog: false,
            show_export_format: ExportFormat::Png,
            new_doc_name: "Untitled".to_string(),
            new_doc_width: 800.0,
            new_doc_height: 600.0,
            new_doc_bg_color: "white".to_string(),
            status_text: "FireCraft ready.".to_string(),
        }
    }

    fn create_new_document(&mut self, name: &str, width: f32, height: f32, bg: &str) {
        let bg_color = match bg {
            "white" => egui::Color32::from_rgb(255, 255, 255),
            "transparent" => egui::Color32::from_argba(0, 0, 0, 0),
            "black" => egui::Color32::from_rgb(0, 0, 0),
            "gray" => egui::Color32::from_rgb(128, 128, 128),
            _ => egui::Color32::from_rgb(255, 255, 255),
        };
        let mut doc = Document::new(name, width, height);
        doc.current_page_mut().bg_color = bg_color;
        self.doc = Some(Mutex::new(doc));
    }
}

impl App for FireCraftApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        ctx.set_theme(egui::Theme::Dark);

        // Keyboard shortcuts
        if ctx.input_mut(|i| i.consume_key(Modifiers::CTRL, Key::N)) {
            self.show_new_doc_dialog = true;
        }
        if ctx.input_mut(|i| i.consume_key(Modifiers::CTRL, Key::S)) {
            self.status_text = "Saved.".to_string();
        }
        if ctx.input_mut(|i| i.consume_key(Modifiers::CTRL, Key::O)) {
            self.status_text = "Open not yet implemented.".to_string();
        }

        self.menu_bar(ctx);
        self.left_panel.ui(ctx);
        if let Some(ref mut doc) = self.doc {
            self.canvas.ui(ctx, doc);
        }
        self.right_panel.ui(ctx);
        self.status_bar(ctx);

        if self.show_new_doc_dialog { self.new_doc_dialog(ctx); }
        if self.show_export_dialog { self.export_dialog(ctx); }
        if self.show_about_dialog {
            ctx.window("About FireCraft").show(|ui| {
                ui.heading("FireCraft");
                ui.label("Modern vector graphics editor. Inspired by Adobe Fireworks CS6.");
                ui.label("Version 0.1.0");
                if ui.button("Close").clicked() { self.show_about_dialog = false; }
            });
        }
    }
}

