use eframe::egui;
use std::sync::Mutex;

use crate::doc::Document;
use crate::paths::{Drawable, PathSegment};

pub struct Canvas {
    pub zoom: f32,
    pub is_drawing: bool,
    pub current_path: Option<PathSegment>,
    pub stroke_color: egui::Color32,
    pub fill_color: egui::Color32,
    pub stroke_width: f32,
    pub last_mouse_pos: Option<egui::Pos2>,
    pub selection_start: Option<egui::Pos2>,
}

impl Canvas {
    pub fn new() -> Self {
        Canvas {
            zoom: 1.0, is_drawing: false, current_path: None,
            stroke_color: egui::Color32::BLACK,
            fill_color: egui::Color32::from_rgba_unmultiplied(0, 0, 0, 0),
            stroke_width: 1.0,
            last_mouse_pos: None, selection_start: None,
        }
    }

    pub fn ui(&mut self, ctx: &egui::Context, doc: &mut Mutex<Document>) {
        let full_size = ctx.screen_rect().size();
        let painter = ctx.layer_painter(egui::LayerId::NEW, egui::SortOrder::Background, full_size);

        let doc = doc.lock().unwrap();
        let page = doc.current_page();
        painter.rect(egui::Rect::from_min_size(ctx.screen_rect().min, full_size), 0.0, page.bg_color, egui::Stroke::new(1.0, egui::Color32::GRAY));

        // Checkerboard
        if page.bg_color.a() == 0 {
            let ts = 10.0;
            let x_count = (full_size.x / ts).ceil() as i32;
            let y_count = (full_size.y / ts).ceil() as i32;
            for y in 0..y_count {
                for x in 0..x_count {
                    let c = if (x + y) % 2 == 0 { egui::Color32::from_rgb(200, 200, 200) } else { egui::Color32::from_rgb(240, 240, 240) };
                    let r = egui::Rect::from_min_size(ctx.screen_rect().min + egui::vec2(x as f32 * ts, y as f32 * ts), egui::vec2(ts, ts));
                    painter.rect(r, 0.0, c, egui::Stroke::NONE);
                }
            }
        }

        // Draw layers
        for layer in &page.layers {
            if !layer.visible { continue; }
            for d in &layer.drawables {
                match d {
                    Drawable::Vector { path, .. } => {
                        if path.points.len() >= 2 {
                            painter.polyline(egui::Shape::line(path.points.clone(), egui::Stroke::new(self.stroke_width, path.stroke_color.unwrap_or(egui::Color32::BLACK))));
                        }
                    }
                    Drawable::Text { text, font_size, color, pos, .. } => {
                        painter.text(*pos, egui::Align2::LEFT_TOP, text.clone(), egui::FontId::proportional(*font_size), *color);
                    }
                    _ => {}
                }
            }
        }

        // Draw current path
        if let Some(ref path) = self.current_path {
            if path.points.len() >= 2 {
                painter.polyline(egui::Shape::line(path.points.clone(), egui::Stroke::new(self.stroke_width, path.stroke_color.unwrap_or(egui::Color32::BLACK))));
            }
        }

        // Selection rect
        if self.is_drawing {
            if let Some(start) = self.selection_start {
                if let Some(pos) = self.last_mouse_pos {
                    let rect = egui::Rect::from_min_max(start, pos);
                    painter.rect_stroke(rect, 1.0, egui::Color32::YELLOW);
                }
            }
        }

        // Grid
        let gs = 20.0;
        let sk = egui::Stroke::new(0.5, egui::Color32::from_rgb(180, 180, 180));
        for x in 0..(full_size.x as usize / 20) {
            let x = x as f32 * gs + ctx.screen_rect().min.x;
            painter.vline(x, ctx.screen_rect().min.y..ctx.screen_rect().min.y + full_size.y, sk);
        }
        for y in 0..(full_size.y as usize / 20) {
            let y = y as f32 * gs + ctx.screen_rect().min.y;
            painter.hline(ctx.screen_rect().min.x..ctx.screen_rect().min.x + full_size.x, y, sk);
        }
    }
}

