use eframe::egui;
use crate::page::Page;

#[derive(Debug, Clone)]
pub struct Document {
    pub pages: Vec<Page>,
    pub current_page_index: usize,
    pub name: String,
    pub path: Option<String>,
    pub history: Vec<String>,
    pub history_index: usize,
}

impl Document {
    pub fn new(name: &str, width: f32, height: f32) -> Self {
        Document {
            pages: vec![Page::new(name, width, height, egui::Color32::WHITE)],
            current_page_index: 0,
            name: name.to_string(),
            path: None,
            history: Vec::new(),
            history_index: 0,
        }
    }
    pub fn current_page(&self) -> &Page { &self.pages[self.current_page_index] }
    pub fn current_page_mut(&mut self) -> &mut Page { &mut self.pages[self.current_page_index] }
    pub fn add_page(&mut self, name: &str, width: f32, height: f32) {
        self.pages.push(Page::new(name, width, height, egui::Color32::WHITE));
    }
    pub fn save_state(&mut self, description: &str) {
        self.history.truncate(self.history_index);
        self.history.push(description.to_string());
        self.history_index = self.history.len();
    }
    pub fn undo(&mut self) -> bool {
        if self.history_index > 0 { self.history_index -= 1; true } else { false }
    }
    pub fn redo(&mut self) -> bool {
        if self.history_index < self.history.len() { self.history_index += 1; true } else { false }
    }
}

#[derive(Debug, Clone)]
pub struct History {
    pub states: Vec<String>,
    pub index: usize,
}

impl History {
    pub fn new() -> Self { History { states: Vec::new(), index: 0 } }
    pub fn push(&mut self, desc: &str) {
        self.states.truncate(self.index);
        self.states.push(desc.to_string());
        self.index = self.states.len();
    }
    pub fn undo(&mut self) -> bool { if self.index > 0 { self.index -= 1; true } else { false } }
    pub fn redo(&mut self) -> bool { if self.index < self.states.len() { self.index += 1; true } else { false } }
}

