        painter.rect(screen, 0.0, page.bg_color, egui::Stroke::new(1.0, egui::Color32::GRAY));

        // Checkerboard for transparent bg
        if page.bg_color.a() == 0 {
            let ts = 10.0;
            let x_count = (screen.size().x / ts).ceil() as i32;
            let y_count = (screen.size().y / ts).ceil() as i32;
            for y in 0..y_count {
                for x in 0..x_count {
                    let c = if (x + y) % 2 == 0 { egui::Color32::from_rgb(200,200,200) } else { egui::Color32::from_rgb(240,240,240) };
                    let r = egui::Rect::from_min_size(
                        screen.min + egui::vec2(x as f32 * ts, y as f32 * ts), egui::vec2(ts, ts));
                    painter.rect(r, 0.0, c, egui::Stroke::NONE);
                }
            }
        }

        // Draw layers
        for layer in &page.layers {
            if !layer.visible { continue; }
            for d in &layer.drawables {
                match d {
                    Drawable::Vector { path, .. } => {
                        if path.points.len() >= 2 {
                            painter.add(egui::Shape::line(path.points.clone(), egui::Stroke::new(self.stroke_width, path.stroke_color.unwrap_or(egui::Color32::BLACK))));
                        }
                    }
                    Drawable::Text { text, font_size, color, pos, .. } => {
                        painter.text(*pos, egui::Align2::LEFT_TOP, text.clone(), egui::FontId::proportional(*font_size), *color);
                    }
                    _ => {}
                }
            }
        }

        // Current path
        if let Some(ref path) = self.current_path {
            if path.len() >= 2 {
                painter.add(egui::Shape::line(path.clone(), egui::Stroke::new(self.stroke_width, self.stroke_color)));
            }
        }

        // Selection rect
        if self.is_drawing {
            if let Some(start) = self.selection_start {
                if let Some(pos) = self.last_mouse_pos {
                    let rect = egui::Rect::from_min_max(start, pos);
                    painter.rect_stroke(rect, 1.0, (1.0, egui::Color32::YELLOW).into());
                }
            }
        }

        // Grid
        let gs = 20.0;
        let sk = egui::Stroke::new(0.5, egui::Color32::from_rgb(180,180,180));
        let x_max = (screen.min.x + screen.size().x);
        let y_max = (screen.min.y + screen.size().y);
        for x in 0..=(screen.size().x as usize / 20) {
            let x = x as f32 * gs + screen.min.x;
            painter.vline(x, screen.min.y..y_max, sk);
        }
        for y in 0..=(screen.size().y as usize / 20) {
            let y = y as f32 * gs + screen.min.y;
            painter.hline(screen.min.x..x_max, y, sk);
        }
    }
}

use eframe::egui;
use crate::tools::Tool;

pub struct LeftPanel {
    pub selected_tool: Tool,
    pub layer_list: Vec<String>,
    pub selected_layer: usize,
}

pub struct RightPanel {
    pub properties: Vec<(String, String)>,
}

impl LeftPanel {
    pub fn new() -> Self {
        LeftPanel {
            selected_tool: Tool::Select,
            layer_list: vec!["Layer 1".to_string()],
            selected_layer: 0,
        }
    }
    pub fn ui(&mut self, ctx: &egui::Context) {
        egui::SidePanel::left("tools").default_width(40.0).show(ctx, |ui| {
            let icons = vec![
                (Tool::Select, "L"), (Tool::Pen, "P"), (Tool::Line, "|"),
                (Tool::Rectangle, "R"), (Tool::Ellipse, "O"), (Tool::Text, "T"),
                (Tool::Brush, "B"), (Tool::Eraser, "E"), (Tool::Eyedropper, "I"),
                (Tool::ColorPicker, "C"), (Tool::Hand, "H"), (Tool::Zoom, "Z"),
                (Tool::Slice, "S"),
            ];
            for (tool, icon) in icons {
                let resp = ui.selectable_value(&mut self.selected_tool, tool, icon);
                if self.selected_tool == tool {
                    ui.ctx().style_mut(|s| {
                        s.visuals.selection.bg_color = egui::Color32::from_rgb(60, 60, 120);
                    });
                }
            }
        });
    }
}

impl RightPanel {
    pub fn new() -> Self {
        RightPanel {
            properties: vec![
                ("Position X".to_string(), "0".to_string()),
                ("Position Y".to_string(), "0".to_string()),
                ("Width".to_string(), "0".to_string()),
                ("Height".to_string(), "0".to_string()),
                ("Rotation".to_string(), "0".to_string()),
                ("Opacity".to_string(), "100%".to_string()),
                ("Blend Mode".to_string(), "Normal".to_string()),
            ],
        }
    }
    pub fn ui(&mut self, ctx: &egui::Context) {
        egui::SidePanel::right("properties").default_width(220.0).show(ctx, |ui| {
            ui.heading("Properties");
            ui.separator();
            for (name, val) in &mut self.properties {
                ui.horizontal(|ui| { ui.label(name.clone()); ui.text_edit_singleline(val); });
            }
            ui.separator();
            ui.heading("Symbol Library");
            ui.label("No symbols defined");
        });
    }
}

