fn main() {
    let args: Vec<String> = std::env::args().collect();
    let screenshot_path = if args.len() > 1 && args[1] == "--screenshot" && args.len() > 2 {
        Some(args[2].clone())
    } else {
        None
    };

    let native_options = eframe::NativeOptions {
        viewport: eframe::egui::ViewportBuilder::default()
            .with_active(false)
            .with_titlebar_shown(true)
            .with_inner_size([1400.0, 900.0])
            .build(),
        ..Default::default()
    };

    let result = eframe::run_native(
        "FireCraft",
        native_options,
        Box::new(|cc| {
            Ok(Box::new(app::FireCraftApp::new(cc, screenshot_path.clone())))
        }),
    );

    if let Some(path) = screenshot_path {
        // Take screenshot after the app exits
        if let Ok(bytes) = std::fs::read(&path) {
            let _ = bytes; // Already written by egui
        }
    }

    let _ = result;
}

