fn update(&mut self, ctx: &egui::Context, frame: &mut eframe::Frame) {
    self.frame_count += 1;

    // Screenshot mode: save after ~120 frames
    if let Some(ref path) = self.screenshot_path {
        if self.frame_count > 120 {
            if let Some(repo) = frame.info() {
                if let Some(tex) = repo.viewport().tex_color() {
                    let img = egui::ColorImage::from_rgba_unmultiplied(
                        ctx.screen_rect().size().ceil().into(), tex.clone());
                    if let Ok(buf) = img.to_rgba8() {
                        let image = image::DynamicImage::new_rgba8(
                            ctx.screen_rect().size().x as u32,
                            ctx.screen_rect().size().y as u32, buf);
                        if let Err(e) = image.save(path) {
                            eprintln!("Screenshot save error: {}", e);
                        }
                    }
                }
            }
            std::process::exit(0);
        }
    }

    // Dark theme

// Screenshot mode: save after ~120 frames
if let Some(ref path) = self.screenshot_path {
    if self.frame_count > 120 {
        if let Some(img) = ctx.try_take_epaint_screenshot() {
            if let Ok(buf) = img.clone().to_rgba8() {
                let image = image::DynamicImage::new_rgba8(
                    img.width(), img.height(), buf);
                if let Err(e) = image.save(path) {
                    eprintln!("Screenshot save error: {}", e);
                }
            }
        }
        std::process::exit(0);
    }
}

