use eframe::egui::{Color32, Pos2, Vec2};

#[derive(Debug, Clone)]
pub enum Shape {
    Rect { min: Vec2, max: Vec2, filled: bool },
    Ellipse { center: Vec2, radius: Vec2, filled: bool },
    Line { a: Vec2, b: Vec2 },
    Path { points: Vec<Vec2>, closed: bool },
    Text { at: Vec2, text: String, size: f32 },
    Bitmap { at: Vec2, pixels: Vec<u8>, size: Vec2 },
}

impl Shape {
    pub fn bounds(&self) -> Option<(Vec2, Vec2)> {
        match self {
            Shape::Rect { min, max, .. } => Some((min.min(*max), min.max(*max))),
            Shape::Ellipse { center, radius, .. } => {
                let lo = Vec2::new(center.x - radius.x, center.y - radius.y);
                let hi = Vec2::new(center.x + radius.x, center.y + radius.y);
                Some((lo, hi))
            }
            Shape::Line { a, b } => Some((a.min(*b), a.max(*b))),
            Shape::Path { points, .. } if !points.is_empty() => {
                let mut lo = points[0];
                let mut hi = points[0];
                for p in points {
                    lo = lo.min(*p);
                    hi = hi.max(*p);
                }
                Some((lo, hi))
            }
            Shape::Text { at, size, .. } => {
                let w = 0.55 * size * 8.0;
                let h = size * 1.2;
                Some((*at, Vec2::new(at.x + w, at.y - h)))
            }
            Shape::Bitmap { at, size, .. } => {
                Some((*at, Vec2::new(at.x + size.x, at.y + size.y)))
            }
        }
    }
}

use eframe::egui::{Color32, Vec2};

use crate::shape::Shape;

#[derive(Debug, Clone)]
pub struct Obj {
    pub kind: Shape,
    pub name: String,
    pub fill: Option<Color32>,
    pub stroke: Option<Color32>,
    pub width: f32,
    pub visible: bool,
    pub locked: bool,
}

impl Obj {
    pub fn new(kind: Shape, fill: Option<Color32>, stroke: Option<Color32>) -> Self {
        Obj {
            kind,
            name: String::new(),
            fill,
            stroke,
            width: 1.0,
            visible: true,
            locked: false,
        }
    }

    pub fn translate(&mut self, offset: Vec2) {
        match &mut self.kind {
            Shape::Rect { min, max, .. } => { *min += offset; *max += offset; }
            Shape::Ellipse { center, .. } => { *center += offset; }
            Shape::Line { a, b } => { *a += offset; *b += offset; }
            Shape::Path { points, .. } => { for p in points { *p += offset; } }
            Shape::Text { at, .. } => { *at += offset; }
            Shape::Bitmap { at, .. } => { *at += offset; }
        }
    }
}

#[derive(Debug, Clone)]
pub struct Layer {
    pub name: String,
    pub visible: bool,
    pub locked: bool,
    pub opacity: f32,
    pub objects: Vec<Obj>,
}

impl Layer {
    pub fn new(name: &str) -> Self {
        Layer {
            name: name.to_string(),
            visible: true,
            locked: false,
            opacity: 1.0,
            objects: Vec::new(),
        }
    }
}

#[derive(Debug, Clone)]
pub struct Page {
    pub name: String,
    pub width: f32,
    pub height: f32,
    pub layers: Vec<Layer>,
    pub bg_color: Color32,
}

impl Page {
    pub fn new(name: &str, w: f32, h: f32, bg: Color32) -> Self {
        Page {
            name: name.to_string(),
            width: w,
            height: h,
            layers: vec![Layer::new("Layer 1")],
            bg_color: bg,
        }
    }
}

#[derive(Debug, Clone)]
pub struct DocState {
    pub label: String,
    pub page: Page,
}

#[derive(Debug, Clone)]
pub struct Document {
    pub pages: Vec<Page>,
    pub current_page_index: usize,
    pub name: String,
    pub zoom: f32,
    pub pan: Vec2,
    pub history: Vec<DocState>,
    pub history_index: usize,
}

impl Document {
    pub fn new(name: &str, w: f32, h: f32, bg: Color32) -> Self {
        Document {
            pages: vec![Page::new(name, w, h, bg)],
            current_page_index: 0,
            name: name.to_string(),
            zoom: 1.0,
            pan: Vec2::ZERO,
            history: Vec::new(),
            history_index: 0,
        }
    }

    pub fn page(&self) -> &Page {
        &self.pages[self.current_page_index]
    }

    pub fn page_mut(&mut self) -> &mut Page {
        &mut self.pages[self.current_page_index]
    }

    pub fn snapshot(&self, label: &str) -> DocState {
        DocState {
            label: label.to_string(),
            page: self.page().clone(),
        }
    }

    pub fn restore(&mut self, snap: &DocState) {
        let p = self.pages.get_mut(self.current_page_index).unwrap();
        p.name.clone_from(&snap.page.name);
        p.width = snap.page.width;
        p.height = snap.page.height;
        p.layers = snap.page.layers.clone();
        p.bg_color = snap.page.bg_color;
    }

    pub fn undo(&mut self) -> bool {
        if self.history_index > 0 {
            self.history_index -= 1;
            true
        } else {
            false
        }
    }

    pub fn redo(&mut self) -> bool {
        if self.history_index < self.history.len() {
            self.history_index += 1;
            true
        } else {
            false
        }
    }
}

use eframe::egui::Color32;

#[derive(Debug, Clone, PartialEq)]
pub enum Format { Png, Jpg, Svg, Gif, Webp, Bmp, Html }

impl Format {
    pub fn extension(&self) -> &str {
        match self {
            Format::Png => "png",
            Format::Jpg => "jpg",
            Format::Svg => "svg",
            Format::Gif => "gif",
            Format::Webp => "webp",
            Format::Bmp => "bmp",
            Format::Html => "html",
        }
    }

    pub fn name(&self) -> &str {
        match self {
            Format::Png => "PNG Image",
            Format::Jpg => "JPEG Image",
            Format::Svg => "SVG Vector",
            Format::Gif => "GIF Image",
            Format::Webp => "WebP Image",
            Format::Bmp => "BMP Image",
            Format::Html => "HTML Document",
        }
    }

    pub fn to_image(&self, pixels: &[u8], w: u32, h: u32) -> Option<image::DynamicImage> {
        match self {
            Format::Png => Some(image::DynamicImage::ImageRgba8(
                image::RgbaImage::from_raw(w, h, pixels.to_vec())?
            )),
            Format::Jpg => {
                let img = image::DynamicImage::ImageRgba8(
                    image::RgbaImage::from_raw(w, h, pixels.to_vec())?
                );
                Some(img.to_rgba8().into_rgba8().into())
            }
            _ => None, // SVG, GIF, WebP, BMP, HTML need special handling
        }
    }
}

/// Simple SVG export - creates a basic SVG from the document's shapes.
pub fn export_svg(page: &crate::doc::Page, width: f32, height: f32) -> String {
    let mut svg = format!("<svg width=\"{}\" height=\"{}\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 {} {}\">\n",
        width, height, width, height);
    for layer in &page.layers {
        if !layer.visible { continue; }
        for obj in &layer.objects {
            match &obj.kind {
                crate::shape::Shape::Rect { min, max, .. } => {
                    let x = min.x.min(max.x);
                    let y = min.y.min(max.y);
                    let w = (max.x - min.x).abs();
                    let h = (max.y - min.y).abs();
                    if let Some(fill) = obj.fill {
                        svg.push_str(&format!("<rect x=\"{:.1}\" y=\"{:.1}\" width=\"{:.1}\" height=\"{:.1}\" fill=\"#{:02x}{:02x}{:02x}\"/>\n", x, y, w, h, fill.r(), fill.g(), fill.b()));
                    }
                    if let Some(stroke) = obj.stroke {
                        svg.push_str(&format!("<rect x=\"{:.1}\" y=\"{:.1}\" width=\"{:.1}\" height=\"{:.1}\" stroke=\"#{:02x}{:02x}{:02x}\" stroke-width=\"{}\" fill=\"none\"/>\n", x, y, w, h, stroke.r(), stroke.g(), stroke.b(), obj.width));
                    }
                }
                crate::shape::Shape::Ellipse { center, radius, .. } => {
                    if let Some(fill) = obj.fill {
                        svg.push_str(&format!("<ellipse cx=\"{:.1}\" cy=\"{:.1}\" rx=\"{:.1}\" ry=\"{:.1}\" fill=\"#{:02x}{:02x}{:02x}\"/>\n", center.x, center.y, radius.x, radius.y, fill.r(), fill.g(), fill.b()));
                    }
                    if let Some(stroke) = obj.stroke {
                        svg.push_str(&format!("<ellipse cx=\"{:.1}\" cy=\"{:.1}\" rx=\"{:.1}\" ry=\"{:.1}\" stroke=\"#{:02x}{:02x}{:02x}\" stroke-width=\"{}\" fill=\"none\"/>\n", center.x, center.y, radius.x, radius.y, stroke.r(), stroke.g(), stroke.b(), obj.width));
                    }
                }
                crate::shape::Shape::Text { at, text, size } => {
                    svg.push_str(&format!("<text x=\"{:.1}\" y=\"{:.1}\" font-size=\"{}\" fill=\"#{:02x}{:02x}{:02x}\">{}</text>\n", at.x, at.y, size, 0, 0, 0, text));
                }
                _ => {}
            }
        }
    }
    svg.push_str("</svg>");
    svg
}

