//! FireCraft — a modern, dark-first raster and vector editor in the shape of
//! Adobe Fireworks CS6.

mod app;
mod canvas;
mod colors;
mod constants;
mod doc;
mod formats;
mod icons;
mod panels;
mod theme;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut screenshot_path: Option<String> = None;
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--screenshot" if i + 1 < args.len() => {
                screenshot_path = Some(args[i + 1].clone());
                i += 2;
            }
            _ => i += 1,
        }
    }

    let w = constants::DEFAULT_WIDTH as f32;
    let h = constants::DEFAULT_HEIGHT as f32;
    let mut viewport = eframe::egui::ViewportBuilder::default()
        .with_inner_size([w, h])
        .with_min_inner_size([1100.0, 700.0])
        .with_title("FireCraft")
        .with_app_id("firecraft.editor");

    if screenshot_path.is_some() {
        viewport = viewport.with_active(false);
        #[cfg(target_os = "windows")]
        {
            viewport = viewport.with_window_level(eframe::egui::WindowLevel::AlwaysOnBottom);
        }
    }

    let native_options = if screenshot_path.is_some() {
        // Use raw window handle to capture screenshot after drawing
        eframe::NativeOptions {
            viewport,
            event_loop_builder: Box::new(|builder| {
                builder.with_allow_screenshot(true)
            }),
            ..Default::default()
        }
    } else {
        eframe::NativeOptions {
            viewport,
            ..Default::default()
        }
    };

    let path_for_closure = screenshot_path.clone();
    let app = Box::new(app::FireCraft::new(path_for_closure));
    eframe::run_native("FireCraft", native_options, Box::new(move |_cc| Ok(app)))
        .expect("FireCraft could not start");
}

