// Capture screenshot: render egui to CPU buffer and save as PNG
let done = self.screenshot_done.clone();
let path = path.clone();
let font_set = ui.ctx().font_set();
let shapes = font_set.fonts(&egui::FontOptions::default()).iter()
    .flat_map(|f| f.glyphs(&egui::FontOptions::default()));
let pixels = ui.ctx().tessellate(font_set.shapes(&egui::FontOptions::default(), 1.0));
let rect = ui.ctx().screen_rect();
let ppr = ui.ctx().pixels_per_point();
let w = (rect.width() * ppr) as usize;
let h = (rect.height() * ppr) as usize;
if w > 0 && h > 0 {
    let mut buf = vec![0u8; w * h * 4];
    for mesh in &pixels {
        let color = egui::Color32::from_rgba_unmultiplied(255, 255, 255, 255);
        for i in 0..mesh.vertices.len() {
            let v = &mesh.vertices[i];
            let x = (v.pos.x * ppr) as usize;
            let y = (v.pos.y * ppr) as usize;
            if x < w && y < h {
                let idx = (y * w + x) * 4;
                buf[idx] = color.r();
                buf[idx + 1] = color.g();
                buf[idx + 2] = color.b();
                buf[idx + 3] = color.a();
            }
        }
    }
    if let Some(png) = image::RgbaImage::from_raw(w as u32, h as u32, buf) {
        let _ = png.save(&path);
        done.store(true, std::sync::atomic::Ordering::Relaxed);
    }
}
if done.load(std::sync::atomic::Ordering::Relaxed) {
    std::process::exit(0);
