            #[cfg(target_os = "windows")]
            {
                use windows::Win32::Foundation::{GetWindowRect, HWND, RECT};
                use windows::Win32::Graphics::Gdi::{
                    BitBlt, CreateCompatibleDC, CreateCompatibleBitmap,
                    SelectObject, DeleteObject, DeleteDC, GetDC, ReleaseDC,
                };

                // Get the window handle from eframe — we can use GetForegroundWindow
                // or enumerate windows. Since the window is AlwaysOnBottom,
                // we need to find it by title.
                let hwnd = find_firecraft_window();
                if let Some(hwnd) = hwnd {
                    let hdc_src = unsafe { GetDC(hwnd) };
                    let hdc_mem = unsafe { CreateCompatibleDC(hdc_src) };
                    let rect = unsafe { GetWindowRect(hwnd) };
                    let width = (rect.right - rect.left) as u32;
                    let height = (rect.bottom - rect.top) as u32;
                    let hbm = unsafe {
                        CreateCompatibleBitmap(
                            hdc_src,
                            width as i32,
                            height as i32,
                        )
                    };
                    let hbm_old = unsafe { SelectObject(hdc_mem, hbm) };
                    unsafe { BitBlt(hdc_mem, 0, 0, width as i32, height as i32, hdc_src, 0, 0, 0x00CC0020 /* SRCCOPY*/) };
                    unsafe { SelectObject(hdc_mem, hbm_old) };

