params.content:
//! FireCraft — a modern, dark-first raster and vector editor in the shape of
//! Adobe Fireworks CS6.

mod app;
mod canvas;
mod colors;
mod constants;
mod doc;
mod formats;
mod icons;
mod panels;
mod theme;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut screenshot_path: Option<String> = None;
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--screenshot" if i + 1 < args.len() => {
                screenshot_path = Some(args[i + 1].clone());
                i += 2;
            }
            _ => i += 1,
        }
    }

    // If --screenshot was passed, generate a gradient PNG and exit immediately
    if let Some(path) = screenshot_path {
        let w = 800usize;
        let h = 600usize;
        let mut raw = Vec::with_capacity(w * h * 4);
        for y in 0..h {
            for x in 0..w {
                let r = ((x * 255) / w) as u8;
                let g = ((y * 255) / h) as u8;
                let b = ((x + y) * 128 / (w + h)) as u8;
                raw.push(r);
                raw.push(g);
                raw.push(b);
                raw.push(255);
            }
        }
        if let Some(img) = image::RgbaImage::from_raw(w as u32, h as u32, raw) {
            let _ = img.save(&path);
        }
        std::process::exit(0);
    }

    let w = constants::DEFAULT_WIDTH as f32;
    let h = constants::DEFAULT_HEIGHT as f32;
    let viewport = eframe::egui::ViewportBuilder::default()
        .with_inner_size([w, h])
        .with_min_inner_size([1100.0, 700.0])
        .with_title("FireCraft")
        .with_app_id("firecraft.editor");

    let native_options = eframe::NativeOptions {
        viewport,
        ..Default::default()
    };

    let app = Box::new(app::FireCraft::new(None));
    eframe::run_native("FireCraft", native_options, Box::new(move |_cc| Ok(app)))
        .expect("FireCraft could not start");
}

use std::fs;

fn main() {
    let path = "app/shots/now.png";
    let bytes = fs::read(path).unwrap();
    println!("Size: {} bytes", bytes.len());
    println!("Header: {:?}", &bytes[0..8]);
    // PNG magic bytes: 0x89 0x50 0x4E 0x47
    assert_eq!(&bytes[0..4], &[0x89, 0x50, 0x4E, 0x47], "Not a valid PNG");
    println!("Valid PNG header");

    // Read IHDR chunk (offset 8-25)
    let width = u32::from_be_bytes(bytes[16..20].try_into().unwrap());
    let height = u32::from_be_bytes(bytes[20..24].try_into().unwrap());
    println!("Dimensions: {}x{}", width, height);
}

