                // Show color swatches
                let cols = 10usize;
                ui.horizontal_wrapped(|ui| {
                    for &swatch in &app.swatches[..std::cmp::min(app.swatches.len(), cols * 5)] {
                        if ui.button(RichText::from(
                            format!("{:02X}", swatch.r())
                        )).visuals_mut(|v| v.fg_stroke = Stroke::new(1.0, swatch)) {
                            app.fill = swatch;
                        }
                    }
                });
