        let layer = app.selected_layer;
        if let Some(obj) = app.doc.page().layers.get(layer).and_then(|l| l.objects.get(idx)) {
            // Object name field
            ui.horizontal(|ui| {
                ui.label(RichText::from("Name:").strong());
                let mut name = obj.name.clone();
                ui.add(egui::TextEdit::singleline(&mut name).desired_width(120.0));
                if name != obj.name {
                    app.set_selected_name(name);
                }
            });

            // Fill color with swatch grid
            if ui.checkbox(
                &obj.fill.is_some(),
                "Fill enabled"
            ).changed() {
                if obj.fill.is_some() {
                    app.set_selected_fill(None);
                } else {
                    app.set_selected_fill(Some(app.fill));
                }
            }
            if obj.fill.is_some() {
                // Swatch grid
                let cols = 6;
                let swatch_size = 18.0;
                ui.horizontal_wrapped(|ui| {
                    for &swatch in &app.swatches {
                        let btn = ui.add(egui::Button::new(
                            RichText::from(format!("{:02X}", swatch.r())).monospace()
                        ).frame(false).min_size(egui::vec2(swatch_size, swatch_size)));
                        if btn.clicked() {
                            app.set_selected_fill(Some(swatch));
                        }
                        // Show color rectangle
                        if let Some(color_tex) = swatch_to_texture(ui.ctx(), swatch) {
                            let prev = ui.add(egui::Image::new(color_tex).min_size(egui::vec2(20.0, 20.0)));
                            if prev.clicked() {
                                app.set_selected_fill(Some(swatch));
                            }
                        }
                    }
                });

                // Stroke color
                ui.horizontal(|ui| {
                    ui.label(RichText::from("Stroke:").strong());
                    ui.color_button("#", app.stroke);
                });

                // Stroke width
                ui.horizontal(|ui| {
                    ui.label(RichText::from("Stroke width:").strong());
                    ui.add(egui::Slider::new(&mut app.stroke_width, 0.0..=50.0).text("px"));
                });
            }
        }
    } else {
        ui.label("Nothing selected");
    }
}

/// Convert a Color32 to a texture for display in swatches
fn swatch_to_texture(ctx: &egui::Context, color: Color32) -> Option<egui::TextureHandle> {
    let pixels = vec![color];
    let image = egui::ColorImage::new([1, 1], pixels);
    let tex = ctx.load_texture(
        format!("swatch-{:x}", color.to_u32()),
        image,
        egui::TextureOptions::default(),
    );
    Some(tex)
}

