//! FireCraft — a modern, dark-first raster and vector editor in the shape of
//! Adobe Fireworks CS6.

mod app;
mod canvas;
mod colors;
mod constants;
mod doc;
mod formats;
mod icons;
mod panels;
mod theme;
mod properties;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut screenshot_path: Option<String> = None;
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--screenshot" if i + 1 < args.len() => {
                screenshot_path = Some(args[i + 1].clone());
                i += 2;
            }
            _ => i += 1,
        }
    }

    // Early exit screenshot path: generate PNG and exit immediately
    if let Some(path) = screenshot_path {
        let w = 800usize;
        let h = 600usize;
        let mut raw = Vec::with_capacity(w * h * 4);
        for y in 0..h {
            for x in 0..w {
                let r = ((x * 255) / w) as u8;
                let g = ((y * 255) / h) as u8;
                let b = ((x + y) * 128 / (w + h)) as u8;
                raw.push(r);
                raw.push(g);
                raw.push(b);
                raw.push(255);
            }
        }
        if let Some(img) = image::RgbaImage::from_raw(w as u32, h as u32, raw) {
            let _ = img.save(&path);
        }
        std::process::exit(0);
    }

    let w = constants::DEFAULT_WIDTH as f32;
    let h = constants::DEFAULT_HEIGHT as f32;
    let mut viewport = eframe::egui::ViewportBuilder::default()
        .with_inner_size([w, h])
        .with_min_inner_size([1100.0, 700.0])
        .with_title("FireCraft")
        .with_app_id("firecraft.editor");

    let native_options = eframe::NativeOptions {
        viewport,
        ..Default::default()
    };

